        .status-grid {
            display: grid;
            grid-template-columns: auto 1fr;
            gap: 12px 10px;
            align-items: start;
        }
        .status-label-v2 {
            font-weight: bold;
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 1.1em;
            color: darkgoldenrod;
        }
        .status-value-v2 {
            font-size: 1.05em;
            line-height: 1.6;
            white-space: pre-wrap;
            padding-left: 5px;
            color: #b8860b;
        }
        .status-label-v2.date::before { content: '📅'; }
        .status-label-v2.date::after { content: 'ﾉ'; margin-left: 3px; font-size: 0.9em; opacity: 0.8; }
        .status-label-v2.time::before { content: '🕒'; }
        .status-label-v2.time::after { content: 'ﾉ♡'; margin-left: 3px; font-size: 0.9em; opacity: 0.8; }
        .status-label-v2.weather::before { content: '☀️'; }
        .status-label-v2.location::before { content: '📍'; }
        .status-label-v2.thoughts::before { content: '💭'; }
        .status-label-v2.emotion::before { content: '💖'; animation: heartbeat-slow 1.8s ease-in-out infinite; }
        .status-label-v2.confession::before { content: '💌'; }
        .status-label-v2.clothing::before { content: '👗'; }
        .status-label-v2.breasts::before { content: '😳'; }
        .status-label-v2.vagina::before { content: '💧'; }
        .confession-section {
            grid-column: 1 / -1;
            display: flex;
            align-items: center;
            flex-wrap: wrap;
            margin-top: 8px;
        }
        .confession-progress-v2 {
            border-radius: 8px;
            height: 14px;
            width: 180px;
            display: inline-block;
            overflow: hidden;
            margin-left: 10px;
            border-width: 1px;
            border-style: solid;
            vertical-align: middle;
            background-color: #fff8dc;
            border-color: darkgoldenrod;
        }
        .confession-progress-bar-v2 {
            background: linear-gradient(to right, #ffeb3b, #fbc02d);
            height: 100%;
            transition: width 0.5s ease;
            border-radius: 6px;
        }
        .confession-value {
            margin-left: 8px;
            font-weight: bold;
            color: #ff8c00;
            font-size: 1em;
        }
        @media (max-width: 600px) {
            .lingyue-status-container-v2 {
                padding: 20px 25px;
                margin: 0 10px 15px 10px;
                max-width: none;
            }
            .lingyue-status-header-v2 {
                font-size: 1.4em;
            }
            .status-grid {
                grid-template-columns: 1fr;
                gap: 8px 5px;
            }
            .status-label-v2 {
                font-size: 1.05em;
            }
            .status-value-v2 {
                font-size: 1em;
                padding-left: 0;
            }
            .confession-progress-v2 {
                width: 150px;
            }
        }

        /* --- 2. 小剧场 --- */
        .mini-theater-container {
            background-color: #e1f5fe;
            border: 1px solid #b3e5fc;
            padding: 20px;
            margin: 0 auto 20px auto;
            border-radius: 15px;
            max-width: 700px;
            font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
            line-height: 1.5;
        }
        .scene-description {
            font-size: 1em;
            color: #0277bd;
            margin-bottom: 20px;
            padding-bottom: 15px;
            border-bottom: 1px solid #81d4fa;
            text-align: center;
            font-style: normal;
            font-weight: bold;
        }
        .dialogue-line {
            margin-bottom: 18px;
            display: flex;
            align-items: flex-start;
            gap: 10px;
        }
        .avatar-placeholder {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background-color: #b3e5fc;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.2em;
            color: #01579b;
            flex-shrink: 0;
            overflow: hidden;
        }
        .avatar-placeholder img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            border-radius: 50%;
        }
        .dialogue-character-bubble {
            padding: 12px 15px;
            border-radius: 18px;
            max-width: calc(100% - 50px);
            position: relative;
            word-wrap: break-word;
        }
        .character-name {
            font-size: 0.9em;
            font-weight: bold;
            margin-bottom: 5px;
            display: block;
        }
        .dialogue-line.speaker-A {
            justify-content: flex-start;
        }
        .dialogue-line.speaker-A .avatar-placeholder {
            background-color: #ffccbc;
            color: #bf360c;
        }
        .dialogue-line.speaker-A .dialogue-character-bubble {
            background-color: #ffffff;
            color: #333;
            border: 1px solid #eeeeee;
            border-top-left-radius: 5px;
        }
        .dialogue-line.speaker-B {
            justify-content: flex-end;
            flex-direction: row-reverse;
        }
        .dialogue-line.speaker-B .avatar-placeholder {
            background-color: #c8e6c9;
            color: #1b5e20;
        }
        .dialogue-line.speaker-B .dialogue-character-bubble {
            background-color: #d1f0ff;
            color: #01579b;
            border: 1px solid #b3e5fc;
            border-top-right-radius: 5px;
            text-align: left;
        }
        @media (max-width: 600px) {
            .mini-theater-container {
                padding: 15px;
            }
            .avatar-placeholder {
                width: 35px;
                height: 35px;
                font-size: 1.1em;
            }
            .avatar-placeholder img {
                width: 100%;
                height: 100%;
            }
            .dialogue-character-bubble {
                padding: 10px 12px;
                font-size: 0.95em;
                max-width: calc(100% - 45px);
                border-radius: 15px;
            }
            .dialogue-line {
                gap: 8px;
                margin-bottom: 15px;
            }
            .character-name {
                font-size: 0.85em;
            }
        }

        /* --- 3. 情书 --- */
        .love-letter-container {
            background-color: #fff0f5;
            border: 1px solid #ffc0cb;
            padding: 30px 35px;
            margin: 0 auto 20px auto;
            border-radius: 10px;
            width: auto;
            min-width: 300px;
            font-family: 'Georgia', serif;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.08);
            position: relative;
            overflow: hidden;
            font-size: 1.1em;
        }
        .love-letter-container::before {
            content: '💌';
            position: absolute;
            top: 15px;
            right: 20px;
            font-size: 24px;
            color: #ff69b4;
            opacity: 0.9;
        }
        .love-letter-content {
            white-space: pre-wrap;
            margin-bottom: 35px;
            color: #4a4a4a;
            line-height: 1.8;
            text-align: left;
        }
        .love-letter-meta {
            font-size: 0.95em;
            color: #777;
            text-align: right;
            border-top: 1px dashed #ffc0cb;
            padding-top: 20px;
            margin-top: 25px;
        }
        .love-letter-meta span {
            display: block;
            margin-bottom: 7px;
        }
        .love-letter-signature {
            font-family: 'ZCOOL QingKe HuangYou', cursive;
            font-size: 1.5em;
            color: #c71585;
            margin-top: 15px;
            display: block;
            text-align: right;
        }
        @media (max-width: 600px) {
            .love-letter-container {
                padding: 20px 25px;
                font-size: 1em;
            }
            .love-letter-content {
                margin-bottom: 25px;
                line-height: 1.7;
            }
            .love-letter-meta {
                font-size: 0.9em;
                padding-top: 15px;
                margin-top: 20px;
            }
            .love-letter-signature {
                font-size: 1.4em;
            }
            .love-letter-container::before {
                font-size: 22px;
                top: 12px;
                right: 15px;
            }
        }
    </style>
</head>
<body>

<div class="tavern-frontend">
    <div class="tavern-tabs">
        <button class="tab-button active" onclick="showTavernSection('section-main-content')">🌙 月月</button>
        <button class="tab-button" onclick="showTavernSection('section-status-bar')">💖 状态栏</button>
        <button class="tab-button" onclick="showTavernSection('section-mini-theater')">💬 小剧场</button>
        <button class="tab-button" onclick="showTavernSection('section-love-letter')">💌 情书</button>
    </div>

    <!-- 正文 Section -->
    <div id="section-main-content" class="tavern-section active">
        <div class="main-content-area">$1</div>
    </div>

    <!-- 状态栏 Section -->
    <div id="section-status-bar" class="tavern-section">
        <div class="lingyue-status-container-v2">
            <div class="lingyue-status-header-v2">[$2] 的当前状态</div>
            <div class="status-grid">
                <span class="status-label-v2 date">日期</span><span class="status-value-v2">$3</span>
                <span class="status-label-v2 time">时间</span><span class="status-value-v2">$4</span>
                <span class="status-label-v2 weather">天气</span><span class="status-value-v2">$5</span>
                <span class="status-label-v2 location">地点</span><span class="status-value-v2">$6</span>
                <span class="status-label-v2 thoughts">心声</span><span class="status-value-v2">$7</span>
                <span class="status-label-v2 emotion">情绪</span><span class="status-value-v2">$8</span>
                <div class="confession-section">
                    <span class="status-label-v2 confession">告白决心 ง</span>
                    <div class="confession-progress-v2">
                        <div class="confession-progress-bar-v2" style="width: $9%;"></div>
                    </div>
                    <span class="confession-value">$10%</span>
                </div>
                <span class="status-label-v2 clothing">今日着装</span><span class="status-value-v2">$11</span>
                <span class="status-label-v2 breasts">胸部状态</span><span class="status-value-v2">$12</span>
                <span class="status-label-v2 vagina">秘密花园</span><span class="status-value-v2">$13</span>
            </div>
        </div>
    </div>

    <!-- 小剧场 Section -->
    <div id="section-mini-theater" class="tavern-section">
        <div class="mini-theater-container">
            <div class="scene-description">$14</div>
            <div class="dialogue-content">$15</div>
        </div>
    </div>

    <!-- 情书 Section -->
    <div id="section-love-letter" class="tavern-section">
        <div class="love-letter-container">
            <div class="love-letter-content">$16</div>
            <div class="love-letter-meta">
                <span>$17</span>
                <span>$18</span>
                <span class="love-letter-signature">$19</span>
            </div>
        </div>
    </div>
</div>

<script>
    function showTavernSection(sectionId) {
        var i, sections, buttons;
        sections = document.querySelectorAll('.tavern-section');
        for (i = 0; i < sections.length; i++) {
            sections[i].classList.remove('active');
        }
        buttons = document.querySelectorAll('.tab-button');
        for (i = 0; i < buttons.length; i++) {
            buttons[i].classList.remove('active');
        }

        var activeSection = document.getElementById(sectionId);
        if (activeSection) {
            activeSection.classList.add('active');
        }
        var activeButton = document.querySelector(`.tab-button[onclick="showTavernSection('${sectionId}')"]`);
        if (activeButton) {
            activeButton.classList.add('active');
        }
    }
    document.addEventListener('DOMContentLoaded', function() {
        showTavernSection('section-main-content');
    });
</script>

</body>
</html>
