entries.content:
Key: lingyue_letter_or_diary_display
Value: |
  <%_ const hasSentPoem = _.has(getvar("stat_data"), '凌月.今日已送诗.[0]') && getvar("stat_data")?.['凌月']?.['今日已送诗']?.[0]; _%>
  <%_ const confessionLevel = Number(getvar("stat_data")?.['凌月']?.['告白度']?.[0] || 0); _%>
  <%_ const generateDiary = () => {
        const mood = confessionLevel < 30 ? '冷淡' : confessionLevel < 60 ? '试探' : '亲昵';
        const diaryFragments = [
          '阳光洒在课桌上，窗外的树好像又绿了点。',
          '今天课代表又忙得晕头转向，某人却在偷懒！',
          '新发现的点心店，草莓蛋糕超诱人！',
          '偷偷瞄了{{user}}一眼，哼，果然还是那么迟钝。',
          '作业堆成山，脑子里却想着点心的味道…',
          '看到{{user}}的笑，心跳好像有点快…别告诉他哦！'
        ];
        const moodBasedFragments = {
          冷淡: ['哼，{{user}}又没做作业，真烦！', '窗外的风有点冷，某人能不能别那么迟钝？'],
          试探: ['点心店的蛋糕不错，{{user}}要不要一起去？', '今天心情还行，看到{{user}}笑得挺开心。'],
          亲昵: ['{{user}}的笑有点暖，害我脸红了一下…', '想跟{{user}}聊点什么，可又怕太明显！']
        };
        const selected = [
          diaryFragments[Math.floor(Math.random() * diaryFragments.length)],
          moodBasedFragments[mood][Math.floor(Math.random() * moodBasedFragments[mood].length)]
        ];
        return selected.join(' ');
      }; _%>
  <%_ const generateLetter = () => {
        const mood = confessionLevel < 30 ? '冷淡' : confessionLevel < 60 ? '试探' : '亲昵';
        const letterFragments = [
          '亲爱的{{user}}，',
          '今天的风好像有点甜，',
          '送你那首诗，哼，只是随手写的！',
          '看到你认真看诗的样子，感觉还不错。',
          '别多想，我才不会专门为你写诗呢！',
          '你的笑有点傻，但还挺好看的…'
        ];
        const moodBasedFragments = {
          冷淡: ['别得意，我只是顺手写的诗！', '哼，诗送你了，别老盯着我看！'],
          试探: ['诗还行吧？下次要不要一起去吃点心？', '送诗的时候，心跳得有点快…别笑！'],
          亲昵: ['看到你读诗的笑，心跳有点乱…', '写诗给你，感觉有点特别，哼！']
        };
        const selected = [
          letterFragments[0], // 亲爱的{{user}}
          letterFragments[Math.floor(Math.random() * (letterFragments.length - 1)) + 1],
          moodBasedFragments[mood][Math.floor(Math.random() * moodBasedFragments[mood].length)]
        ];
        return selected.join(' ');
      }; _%>
  <%_ if (_.has(getvar("stat_data"), '凌月.今日已送诗.[0]')) { _%>
    <%_ if (hasSentPoem) { _%>
      <letter-content>
        <%= generateLetter() %>
      </letter-content>
    <%_ } else { _%>
      <letter-content>
        [凌月的小日记片段]
        <%= generateDiary() %>
      </letter-content>
    <%_ } _%>
  <%_ } else { _%>
    [系统通知] 缺失核心变量：凌月.今日已送诗=<%= _.has(getvar("stat_data"), '凌月.今日已送诗.[0]') %>
  <%_ } _%>
