import random
import re
from bisect import bisect_left
from collections import defaultdict, deque
from typing import Dict, List, Tuple

class DynamicCharacter:
    def __init__(self, name: str, initial_traits: Dict[str, float]):
        self.name = name
        self.base_traits = initial_traits.copy()

        # 特质系统
        self.trait_values = defaultdict(float, initial_traits)
        self.trait_weights: Dict[str, float] = {}
        self._normalize_weights()

        # 情感触发系统优化：使用反向映射
        self.word_emotion_map: Dict[str, List[Tuple[str, float]]] = defaultdict(list)
        self._build_emotion_triggers()

        # 记忆系统优化：使用定长队列
        self.context_window = 3
        self.conversation_history: deque = deque(maxlen=self.context_window)

        # 响应系统修复数据结构
        self.response_db = self._build_response_system()
        self.last_used_traits: List[str] = []

        # 系统参数
        self.decay_rate = 0.93
        self.learning_rate = 0.15
        self.context_weight = 0.4

        # 预编译正则表达式
        self.clean_text_re = re.compile(r'[^\w\s]')

    def _build_emotion_triggers(self) -> None:
        """构建情感触发反向映射表"""
        emotion_definitions = {
            'happy': {'happy': 0.3, 'joy': 0.4, 'good': 0.2, 'great': 0.3, 'wonderful': 0.5, 'excited': 0.4},
            'sad': {'sad': 0.4, 'unhappy': 0.3, 'depressed': 0.5, 'lonely': 0.4, 'grief': 0.6},
            'angry': {'angry': 0.5, 'mad': 0.4, 'pissed': 0.6, 'annoyed': 0.3, 'furious': 0.7},
            'curious': {'curious': 0.4, 'why': 0.2, 'how': 0.2, 'what': 0.2, 'explain': 0.3},
            'confident': {'confident': 0.5, 'certain': 0.4, 'sure': 0.3, 'know': 0.2, 'believe': 0.3}
        }
        for emotion, triggers in emotion_definitions.items():
            for word, weight in triggers.items():
                self.word_emotion_map[word].append((emotion, weight))

    def _build_response_system(self):
        """修复响应数据结构"""
        return {
            'happy': [
                ("What a wonderful day!", ['joyful', 'optimistic']),
                ("Everything seems so bright!", ['cheerful', 'positive'])
            ],
            'sad': [
                ("I feel like the world is heavy...", ['melancholy', 'introspective']),
                ("Everything seems so gray today.", ['pensive', 'sensitive'])
            ],
            'angry': [
                ("This is completely unacceptable!", ['assertive', 'frustrated']),
                ("I won't tolerate this anymore!", ['decisive', 'strong-willed'])
            ],
            'curious': [
                ("Could you explain that in more detail?", ['inquisitive', 'attentive']),
                ("What's the story behind this?", ['analytical', 'observant'])
            ],
            'confident': [
                ("I'm certain we can solve this.", ['assertive', 'optimistic']),  # 修复数据结构
                ("This is clearly the best approach.", ['decisive', 'knowledgeable'])
            ]
        }

    def _normalize_weights(self):
        """处理零和情况的安全归一化"""
        total = sum(self.trait_values.values())
        if total <= 0:
            # 重置为初始特质
            self.trait_values = defaultdict(float, self.base_traits)
            total = sum(self.trait_values.values())

        self.trait_weights = {k: (v / total) ** 1.5 for k, v in self.trait_values.items()}

    def _analyze_emotional_context(self, text: str) -> Dict[str, float]:
        """情感分析"""
        scores = defaultdict(float)
        cleaned_text = self.clean_text_re.sub('', text.lower())

        # 使用反向映射加速查询
        for word in cleaned_text.split():
            if word in self.word_emotion_map:
                for emotion, weight in self.word_emotion_map[word]:
                    scores[emotion] += weight * (1 + cleaned_text.count(word)*0.2

        # 标准化情感强度
        max_score = max(scores.values(), default=0)
        if max_score > 0:
            return {emo: (score/max_score)**1.3 for emo, score in scores.items()}
        return {}

    def update_traits(self, user_input: str, feedback: str = None):
        """特质更新"""
        emotion_scores = self._analyze_emotional_context(user_input)

        # 应用衰减和更新
        for trait in self.trait_values:
            # 基础衰减
            self.trait_values[trait] *= self.decay_rate
            # 情感影响
            if trait in emotion_scores:
                delta = emotion_scores[trait] * self.learning_rate
                if feedback:
                    delta *= {'positive': 1.4, 'negative': 0.6}.get(feedback, 1.0)
                self.trait_values[trait] += delta

        # 上下文影响（使用队列自动维护长度）
        if self.conversation_history:
            context_traits = [t for _, traits in self.conversation_history for t in traits]
            counter = defaultdict(int)
            for t in context_traits:
                counter[t] += 1
            for t, count in counter.items():
                self.trait_values[t] += self.context_weight * count

        self._normalize_weights()
        self.conversation_history.append((user_input, list(emotion_scores.keys()))  # 自动截断

    def generate_response(self) -> str:
        """响应生成"""
        # 使用权重采样选择特质
        traits = list(self.trait_weights.items())
        cumulative = []
        current = 0
        for t, w in traits:
            current += w
            cumulative.append(current)

        # 动态选择3个特质
        selected_traits = set()
        while len(selected_traits) < 3:
            rand = random.random() * cumulative[-1]
            idx = bisect_left(cumulative, rand)
            selected_traits.add(traits[idx][0])

        # 构建候选响应
        candidate_responses = []
        for trait in selected_traits:
            if trait in self.response_db:
                for resp, traits in self.response_db[trait]:
                    weight = sum(self.trait_weights[t] for t in traits if t in self.trait_weights)
                    candidate_responses.append((resp, traits, weight))

        if not candidate_responses:
            return "I'm not sure what to say right now."

        # 高效加权选择
        cum_weights = []
        current = 0
        for item in candidate_responses:
            current += item[2]
            cum_weights.append(current)

        rand_val = random.uniform(0, cum_weights[-1])
        index = bisect_left(cum_weights, rand_val)
        chosen_response, response_traits, _ = candidate_responses[index]
        self.last_used_traits = response_traits
        return chosen_response

    def process_feedback(self, feedback_type: str):
        """添加反馈类型验证"""
        valid_feedbacks = {'positive', 'negative', 'neutral'}
        if feedback_type not in valid_feedbacks:
            raise ValueError(f"Invalid feedback type. Expected one of {valid_feedbacks}")

        multiplier = {'positive': 1.5, 'negative': 0.6, 'neutral': 1.0}[feedback_type]
        for trait in self.last_used_traits:
            if trait in self.trait_values:
                self.trait_values[trait] *= multiplier
        self._normalize_weights()

    def long_term_development(self):
        """长期发展"""
        # 基础回归
        for trait, base_val in self.base_traits.items():
            self.trait_values[trait] += (base_val - self.trait_values[trait]) * 0.05

        # 经验积累（仅考虑最近100条对话）
        recent_history = list(self.conversation_history)[-100:]
        trait_counter = defaultdict(int)
        for _, traits in recent_history:
            for t in traits:
                trait_counter[t] += 1

        for trait, count in trait_counter.items():
            if count > 5:
                self.trait_values[trait] *= 1 + (count * 0.01)

        self._normalize_weights()

# 使用示例
hero = DynamicCharacter("Aurora", {
    'happy': 1.2,
    'curious': 0.9,
    'confident': 0.7,
    'sad': 0.5,
    'angry': 0.3
})

# 测试对话
dialogue = [
    ("I'm feeling so excited about this new discovery!", 'positive'),
    ("Why do you think this happened?", 'neutral'),
    ("This is completely unacceptable behavior!", 'negative'),
    ("I'm not sure I understand...", 'positive')
]

for text, feedback in dialogue:
    hero.update_traits(text)
    response = hero.generate_response()
    hero.process_feedback(feedback)
    print(f"Response: {response}")
    print(f"Current traits: {dict(hero.trait_weights)}\n")

